package lk.uniwork.task;
import lk.uniwork.common.ApiException; import lk.uniwork.user.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class DirectTaskService {
 private final DirectTaskRepository tasks; private final UserIdentityService identities; private final UserRepository users; private final IdentityGate gate; private final TaskRepository lifecycleTasks; private final TaskApplicationRepository applications; private final TaskExecutionRepository executions; private final lk.uniwork.user.StudentProfileRepository studentProfiles; private final lk.uniwork.user.TaskPosterProfileRepository posterProfiles;
 public DirectTaskService(DirectTaskRepository tasks,UserIdentityService identities,UserRepository users,IdentityGate gate,TaskRepository lifecycleTasks,TaskApplicationRepository applications,TaskExecutionRepository executions,lk.uniwork.user.StudentProfileRepository studentProfiles,lk.uniwork.user.TaskPosterProfileRepository posterProfiles){this.tasks=tasks;this.identities=identities;this.users=users;this.gate=gate;this.lifecycleTasks=lifecycleTasks;this.applications=applications;this.executions=executions;this.studentProfiles=studentProfiles;this.posterProfiles=posterProfiles;}
 @Transactional public DirectTaskDtos.Response create(String subject,DirectTaskDtos.Create r){var poster=identities.requireTaskPoster(subject);var student=users.findByClerkUserId(r.studentId()).orElseThrow(()->bad("STUDENT_NOT_FOUND","Student not found."));if(student.getRole()!=UserRole.STUDENT)throw bad("STUDENT_REQUIRED","Recipient must be a Student.");gate.requirePosterVerified(poster.getId());var offer=new DirectTask(poster,student,r.description().trim(),r.scheduledAt(),r.amountLkr(),r.locationAddress().trim(),r.latitude(),r.longitude());offer.setCategory(r.category());return response(tasks.save(offer));}
 @Transactional(readOnly=true) public List<DirectTaskDtos.Response> student(String subject){identities.requireStudent(subject);return tasks.findByStudentClerkUserIdOrderByCreatedAtDesc(subject).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<DirectTaskDtos.Response> poster(String subject){identities.requireTaskPoster(subject);return tasks.findByPosterClerkUserIdOrderByCreatedAtDesc(subject).stream().map(this::response).toList();}
 @Transactional public DirectTaskDtos.Response action(String subject,UUID id,DirectTaskDtos.Action r){var task=tasks.findById(id).orElseThrow(()->bad("DIRECT_TASK_NOT_FOUND","Direct task not found."));if(!task.getStudent().getClerkUserId().equals(subject))throw new ApiException(HttpStatus.FORBIDDEN,"DIRECT_TASK_FORBIDDEN","You cannot change this direct task.");if(task.getStatus()!=DirectTaskStatus.SENT)throw bad("DIRECT_TASK_FINALIZED","This offer is awaiting the Task Poster or has already been finalized.");switch(r.action().toUpperCase(Locale.ROOT)){case "ACCEPT"-> {task.accept(); createLifecycleTask(task);}case "DECLINE"->task.decline();case "COUNTER"->{if(r.proposedAmount()==null)throw bad("COUNTER_AMOUNT_REQUIRED","Enter a proposed amount.");task.counter(r.proposedAmount());}default->throw bad("INVALID_DIRECT_TASK_ACTION","Choose accept, decline or counter.");}return response(task);}
 @Transactional public DirectTaskDtos.Response posterAction(String subject,UUID id,DirectTaskDtos.Action r){var task=tasks.findById(id).orElseThrow(()->bad("DIRECT_TASK_NOT_FOUND","Direct task not found."));if(!task.getPoster().getClerkUserId().equals(subject))throw new ApiException(HttpStatus.FORBIDDEN,"DIRECT_TASK_FORBIDDEN","You cannot change this direct task.");if(task.getStatus()!=DirectTaskStatus.COUNTEROFFERED)throw bad("COUNTEROFFER_REQUIRED","There is no pending counteroffer.");switch(r.action().toUpperCase(Locale.ROOT)){case "ACCEPT"-> {task.accept(); createLifecycleTask(task);}case "REJECT"->task.rejectCounter();default->throw bad("INVALID_COUNTER_ACTION","Choose accept or reject.");}return response(task);}
 private DirectTaskDtos.Response response(DirectTask task){var posterName=posterProfiles.findById(task.getPoster().getId()).map(lk.uniwork.user.TaskPosterProfile::getFullName).orElse("Task Poster");var studentName=studentProfiles.findById(task.getStudent().getId()).map(lk.uniwork.user.StudentProfile::getFullName).orElse("Student");return DirectTaskDtos.Response.from(task,posterName,studentName);}
 private void createLifecycleTask(DirectTask direct){if(direct.getLinkedTask()!=null)return;var lifecycle=lifecycleTasks.save(new Task(direct.getPoster(),"Direct task: "+direct.getDescription().substring(0,Math.min(120,direct.getDescription().length())),direct.getDescription(),direct.getAmountLkr(),direct.getScheduledAt(),direct.getLocationAddress(),direct.getLatitude(),direct.getLongitude(),Set.of(),direct.getCategory()));lifecycle.acceptStudent();var application=new TaskApplication(lifecycle,direct.getStudent());application.changeStatus(TaskApplicationStatus.ACCEPTED);applications.save(application);executions.save(new TaskExecution(lifecycle,application,direct.getStudent()));direct.linkTask(lifecycle);}
 private ApiException bad(String code,String msg){return new ApiException(HttpStatus.BAD_REQUEST,code,msg);}
}
